          "claim": "ts-order-service pod CPU limit utilization peaks at 0.994, pinning its container CPU limit during the incident."
        },
        {
          "kind": "metric",
          "sql": "SELECT 'abn' AS p, metric, round(avg(value),3) AS v FROM abnormal_metrics WHERE service_name='ts-order-service' AND metric='k8s.pod.cpu.usage' GROUP BY 1,2 UNION ALL SELECT 'norm', metric, round(avg(value),3) FROM normal_metrics WHERE service_name='ts-order-service' AND metric='k8s.pod.cpu.usage' GROUP BY 1,2",
          "claim": "ts-order-service pod CPU usage averages about 1.5 cores in the incident versus 0.19 cores normally."
        },
        {
          "kind": "metric",
          "sql": "SELECT floor(epoch(time)/30)*30 - (SELECT floor(min(epoch(time))/30)*30 FROM abnormal_metrics) AS sec, round(avg(value),3) AS cpu FROM abnormal_metrics WHERE service_name='ts-order-service' AND metric='k8s.pod.cpu.usage' GROUP BY 1 ORDER BY 1",
          "claim": "ts-order-service CPU climbs to about 3.8 cores around 60–100 seconds into the window, then falls back."
        },
        {
          "kind": "trace",
          "sql": "SELECT floor(epoch(time)/30)*30 - (SELECT floor(min(epoch(time))/30)*30 FROM abnormal_traces) AS sec, count(*) AS n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) AS errs FROM abnormal_traces WHERE service_name='ts-seat-service' AND span_name='POST' AND attr_span_kind='Client' GROUP BY 1 ORDER BY 1",
          "claim": "Seat-service's outgoing POST calls fail only in the first ~100 seconds, the same window as order-service's CPU burst."
        },
        {
          "kind": "log",
          "sql": "SELECT level, substr(message,1,200) AS msg, count(*) AS c FROM abnormal_logs WHERE service_name='ts-seat-service' AND level='SEVERE' GROUP BY 1,2",
          "claim": "Seat-service logs 108 SEVERE 503 errors: upstream connect error, 'Connection refused' on the downstream call."
        }
      ]
    }
  ],
